html:
{# ==============================
   PAYMENT / RECEIPT VOUCHER (SIMPLE)
   - Works for Customer / Supplier / Employee
   - Works for Pay / Receive
   - No accounts
   - No allocations
   - No balances
   - Shows: Party + Amount + Remarks + Reference + Signatures
================================ #}

{% set party_name = doc.party_name or doc.party %}
{% set currency = doc.paid_from_account_currency or doc.paid_to_account_currency or doc.company_currency or doc.currency %}

{% set paid_amt = doc.paid_amount or 0 %}
{% set recv_amt = doc.received_amount or 0 %}

{# Determine voucher type + amount #}
{% if (doc.payment_type or "").lower() == "pay" %}
  {% set voucher_title = "Payment Voucher" %}
  {% set main_label = "Payment Amount" %}
  {% set main_amt = paid_amt %}
{% elif (doc.payment_type or "").lower() == "receive" %}
  {% set voucher_title = "Receipt Voucher" %}
  {% set main_label = "Receipt Amount" %}
  {% set main_amt = recv_amt if recv_amt else paid_amt %}
{% else %}
  {% set voucher_title = "Payment Voucher" %}
  {% set main_label = "Amount" %}
  {% set main_amt = paid_amt if paid_amt else recv_amt %}
{% endif %}

{# Prepared / Approved names (simple + safe) #}
{% set prepared_by_user = doc.owner %}
{% set prepared_by = frappe.db.get_value("User", prepared_by_user, "full_name") or prepared_by_user %}

{# If you later add workflow, replace this with doc.approved_by custom field #}
{% set approved_by_user = doc.modified_by if doc.docstatus == 1 else "" %}
{% set approved_by = (frappe.db.get_value("User", approved_by_user, "full_name") or approved_by_user) if approved_by_user else "" %}

<style>
  .pv-wrap{
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    font-size: 12.5px;
    color:#1f2d3d;
  }

  .pv-title{
    text-align:center;
    margin: 8px 0 10px 0;
  }
  .pv-title h2{
    margin:0;
    font-size: 20px;
    letter-spacing:.8px;
    text-transform: uppercase;
  }
  .pv-title .ref{
    margin-top: 4px;
    color:#6c757d;
    font-size: 11px;
  }

  .pv-divider{
    border:0;
    border-top: 1px solid #212529;
    margin: 10px 0 14px 0;
    opacity: .8;
  }

  .pv-grid{
    width:100%;
    border-collapse: collapse;
    table-layout: fixed;
  }
  .pv-grid td{
    padding: 7px 8px;
    vertical-align: top;
  }
  .pv-k{
    font-weight: 800;
    color:#212529;
    width: 22%;
    white-space: nowrap;
  }
  .pv-v{
    width: 28%;
  }

  .pv-remark{
    white-space: pre-wrap;
    line-height: 1.55;
  }

  .pv-amount-box{
    margin-top: 10px;
    border: 1px solid #e9ecef;
    border-radius: 10px;
    padding: 14px 14px;
    background: #fbfcfd;
  }
  .pv-amount-row{
    display:flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
  }
  .pv-amount-row .lbl{
    font-weight: 900;
    color:#212529;
    font-size: 12px;
  }
  .pv-amount-row .val{
    font-weight: 900;
    font-size: 18px;
    font-variant-numeric: tabular-nums;
  }

  .pv-sign-row{
    margin-top: 42px;
    display:flex;
    justify-content: space-between;
    gap: 18px;
  }
  .pv-sign-box{
    width: 32%;
    text-align:center;
  }
  .pv-sign-line{
    margin-top: 54px;
    border-top: 2px dashed #2f343a;
    padding-top: 6px;
    font-weight: 900;
    font-size: 12px;
  }
  .pv-sign-meta{
    margin-top: 4px;
    font-size: 11px;
    color:#212529;
    font-weight: 700;
    min-height: 14px;
  }
  .pv-sign-note{
    margin-top: 2px;
    color:#6c757d;
    font-size: 11px;
    font-weight: 600;
  }

  .pv-footer{
    margin-top: 22px;
    border-top: 1px solid #e9ecef;
    padding-top: 8px;
    text-align:center;
    font-size: 10.5px;
    color:#6c757d;
  }
</style>

<div class="pv-wrap">
  {{ letter_head }}

  <div class="pv-title">
    <h2>{{ voucher_title }}</h2>
    <div class="ref">Reference No: {{ doc.name }}</div>
  </div>

  <hr class="pv-divider">

  <!-- Main Information -->
  <table class="pv-grid">
    <tr>
      <td class="pv-k">Party Type</td>
      <td class="pv-v">{{ doc.party_type or "-" }}</td>

      <td class="pv-k">Party</td>
      <td class="pv-v">{{ party_name }}</td>
    </tr>

    <tr>
      <td class="pv-k">Posting Date</td>
      <td class="pv-v">{{ doc.posting_date }}</td>

      <td class="pv-k">Posting Time</td>
      <td class="pv-v">{{ doc.posting_time or "-" }}</td>
    </tr>

    <tr>
      <td class="pv-k">Mode of Payment</td>
      <td class="pv-v">{{ doc.mode_of_payment or "-" }}</td>

      <td class="pv-k">{{ main_label }}</td>
      <td class="pv-v">
        {{ frappe.utils.fmt_money(main_amt, currency=currency) }}
      </td>
    </tr>

    {% if doc.reference_no or doc.reference_date %}
    <tr>
      <td class="pv-k">Reference No</td>
      <td class="pv-v">{{ doc.reference_no or "-" }}</td>

      <td class="pv-k">Reference Date</td>
      <td class="pv-v">{{ doc.reference_date or "-" }}</td>
    </tr>
    {% endif %}

    {% if doc.remarks %}
    <tr>
      <td class="pv-k">Remarks</td>
      <td class="pv-v pv-remark" colspan="3">{{ doc.remarks }}</td>
    </tr>
    {% endif %}
  </table>

  <!-- Big Amount Highlight -->
  <div class="pv-amount-box">
    <div class="pv-amount-row">
      <div class="lbl">{{ main_label }}</div>
      <div class="val">{{ frappe.utils.fmt_money(main_amt, currency=currency) }}</div>
    </div>
  </div>

  <!-- Signatures -->
  <div class="pv-sign-row">
    <div class="pv-sign-box">
      <div class="pv-sign-line">Prepared By</div>
      <div class="pv-sign-meta">{{ prepared_by or "-" }}</div>
      <div class="pv-sign-note">Accountant / Cashier Signature</div>
    </div>

    <div class="pv-sign-box">
      <div class="pv-sign-line">Approved By</div>
      <div class="pv-sign-meta">{{ approved_by or "-" }}</div>
      <div class="pv-sign-note">Manager Signature & Stamp</div>
    </div>

    <div class="pv-sign-box">
      <div class="pv-sign-line">Received By</div>
      <div class="pv-sign-meta">{{ party_name }}</div>
      <div class="pv-sign-note">Customer / Supplier / Employee Signature</div>
    </div>
  </div>

  <div class="pv-footer">
    This voucher is system generated. Signatures are required for audit compliance.
  </div>
</div>
